From ef4a9a557d769b5d472c403125716706a0d9cc77 Mon Sep 17 00:00:00 2001
From: Frank de Jonge <info@frankdejonge.nl>
Date: Sat, 22 Aug 2026 14:53:53 +0200
Subject: [PATCH] Report broken utf-8 as a corrupted path.

---
 src/WhitespacePathNormalizer.php     | 3 ++-
 src/WhitespacePathNormalizerTest.php | 2 +-
 2 files changed, 3 insertions(+), 2 deletions(-)

diff --git a/src/WhitespacePathNormalizer.php b/src/WhitespacePathNormalizer.php
index 16d78fa73..7daaf659b 100644
--- a/src/WhitespacePathNormalizer.php
+++ b/src/WhitespacePathNormalizer.php
@@ -22,8 +22,9 @@ public function __construct(bool $allowRelativePathTraversal = true)
     public function normalizePath(string $path): string
     {
         $unixPath = str_replace('\\', '/', $path);
+        $match = preg_match('#\p{C}+#u', $unixPath);

-        if (preg_match('#\p{C}+#u', $unixPath)) {
+        if ($match !== 0) {
             throw CorruptedPathDetected::forPath($path);
         }

diff --git a/src/WhitespacePathNormalizerTest.php b/src/WhitespacePathNormalizerTest.php
index eadbbd37f..3daa547c7 100644
--- a/src/WhitespacePathNormalizerTest.php
+++ b/src/WhitespacePathNormalizerTest.php
@@ -134,7 +134,7 @@ public function rejecting_funky_whitespace(string $path): void

     public static function dpFunkyWhitespacePaths(): iterable
     {
-        return [["some\0/path.txt"], ["s\x09i.php"]];
+        return [["some\0/path.txt"], ["s\x09i.php"], ["foo\x80\x1bbar"]];
     }

     /**
